CREATE DATABASE Customer_Sales;
USE Customer_Sales;

SELECT * FROM customer_data;

SELECT * FROM customer_data LIMIT 1000 OFFSET 0;
SELECT * FROM customer_data LIMIT 1000 OFFSET 1000;
SELECT * FROM customer_data LIMIT 1000 OFFSET 2000;
SELECT * FROM customer_data LIMIT 1000 OFFSET 3000;


-- Q1. What is the total revenue generated by sales vs. female customers?

SELECT SUM(purchase_amount) AS revenue, gender
FROM customer_data
GROUP BY gender;

-- Q2. Which customers used a discount but still spent more than the average  purchase amount?

SELECT customer_id,purchase_amount
FROM customer_data
WHERE discount_applied='Yes' AND purchase_amount >= (SELECT AVG(purchase_amount) FROM customer_data);

-- Q3. Which are the top 5 products with the highest average review rating?

SELECT * FROM customer_data;

SELECT item_purchased ,ROUND(AVG(review_rating),2) AS average_review_rating
FROM customer_data
GROUP BY item_purchased
ORDER BY average_review_rating DESC LIMIT 5;

-- Q4. Compare the average purchase amounts between standards and express shipping.

SELECT shipping_type,ROUND(AVG(purchase_amount),2) AS average_purchase_amount
FROM customer_data
WHERE shipping_type in ('Standard','Express')
GROUP BY shipping_type;

-- Q5. Do subscribed customers spend more? Compare average spend and total revenue between subscribers and non-subscribers.

SELECT AVG(purchase_amount) AS average_purchase_amount,ROUND(SUM(purchase_amount),2) AS total_revenue,subscription_status
FROM customer_data
GROUP BY subscription_status
ORDER BY total_revenue,average_purchase_amount DESC;

-- Q6. Which  5 products have the highest percentage of purchases with discount applied?

SELECT * FROM customer_data;

SELECT item_purchased,
ROUND(SUM(CASE WHEN discount_applied ='Yes' THEN 1 ELSE 0 END)/COUNT(*)*100,2) AS discount_rate
FROM customer_data
GROUP BY item_purchased
ORDER BY discount_rate DESC LIMIT 5;

-- Q7. Segment customer into new,returning and loyal based on their total no. 
-- of previous purchases, and show the total purchase of each segment.

WITH customer_type AS(
SELECT customer_id,previous_purchases,
CASE
	WHEN previous_purchases = 1 THEN 'NEW'
    WHEN previous_purchases BETWEEN 2 AND 10 THEN 'RETURNING'
    ELSE 'LOYAL'
    END AS customer_segment
FROM customer_data
)

SELECT customer_segment,COUNT(*) AS 'Number of customers' 
FROM customer_type
GROUP BY customer_segment;

-- Q8. What are the top 3 most purchased products within each cayegory?

WITH item_counts AS(
SELECT category,
item_purchased,
COUNT(customer_id) AS total_orders,
ROW_NUMBER() OVER(PARTITION BY category ORDER BY COUNT(customer_id) DESC) AS item_rank	
FROM customer_data
GROUP BY category,item_purchased
)

SELECT item_rank,category,item_purchased,total_orders
FROM item_counts
Where item_rank <=3;

-- Q9. Are customers who are repeat buyers (more than 5 previous purchases) also likely to subscribe?

SELECT COUNT(customer_id) AS repeat_buyers ,subscription_status
FROM customer_data
WHERE previous_purchases>5 
GROUP BY subscription_status;

-- Q10. What is the revenue contribution of each age group?

SELECT SUM(purchase_amount) As revenue, age_group
FROM customer_data
GROUP BY age_group
ORDER BY revenue;

























